package com.jarvis.brain;
import java.time.*;import java.util.*;
public final class RuntimeRecoveryConversationTest{
 public static void main(String[]a){ToolRegistry r=new ToolRegistry();int[]tries={0};r.register(new ToolSpec("parking_search",false,Set.of(),Set.of(),"search",ToolExecutionClass.DEVICE_REFLEX),(x,c)->{tries[0]++;return ToolResult.retryableFailure("No parking found. Choose Garage A or Garage B.");});AssistantCore core=new AssistantCore(BrainEngine.createDefault(Clock.fixed(Instant.parse("2026-08-28T18:00:00Z"),ZoneOffset.UTC)),req->new ReasoningResult("local","Searching parking",new Plan("parking",List.of(new PlanStep("parking_search",Map.of(),false)))),r);BrainRuntime runtime=new BrainRuntime(core,r);RuntimeApprovalConversation convo=new RuntimeApprovalConversation(runtime);core.handle("Hey Jarvis");RuntimeSurfacePresentation p=convo.handle("find parking");check(p.state()==AssistantSurfaceState.NEEDS_INPUT,"recovery maps needs input");check(p.primaryAction()==RuntimeSurfaceAction.RETRY,"retry surfaced");int after=tries[0];RuntimeSurfacePresentation side=convo.handle("what were the options?");check(side.state()==AssistantSurfaceState.NEEDS_INPUT,"side question preserves recovery");check(tries[0]==after,"side question cannot silently retry");RuntimeSurfacePresentation cancel=convo.cancelPending();check(cancel.state()==AssistantSurfaceState.IDLE,"cancel clears recovery");System.out.println("RuntimeRecoveryConversationTest passed");}
 private static void check(boolean v,String m){if(!v)throw new AssertionError(m);}
}
